 38		public void act(List<Animal> newAnimals, TimeCycle time) {
 39			incrementAge();
 40			incrementHunger();
 41			battleSickness();
 42			if (isAlive() && isActiveDuring(time)) {
 43				normalAct(newAnimals);
 44			}
