 48		protected void incrementAge() {
 49			age++;
 50			if (age > getMaxAge()) {
 51				setDead();
 52			}
 53		}
 54	
 55	
 56		private boolean canBreed() {
 57			if (age < getBreedingAge()) {
 58				return false;
 59			}
 60	
 61			FieldEnvironment field = getField();
 62			List<Location> adjacent = field.getAdjacentAnimalLocations(getLocation());
 63			Iterator<Location> it = adjacent.iterator();
 64			while (it.hasNext()) {
 65				Location where = it.next();
 66				Animal animalNear = field.getAnimalAt(where);
 67				if (animalNear != null
 68						&& animalNear.getClass().equals(getClass())
 69						&& getGender() != animalNear.getGender()) {
 70					return true;
 71				}
 72			}
 73			return false;
 74		}
 75	
 76	
 77		private int breed() {
 78			int births = 0;
 79			if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
 80				births = rand.nextInt(getMaxLitterSize()) + 1;
 81			}
 82			return births;
 83		}
