 85	
 86		protected void giveBirth(List<Animal> newAnimals) {
 87	
 88	
 89			if (this.getGender() == Gender.FEMALE) {
 90				FieldEnvironment field = getField();
 91				List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
 92				int births = breed();
 93				for (int b = 0; b < births && free.size() > 0; b++) {
 94					Location loc = free.remove(0);
 95					Animal young = species.createAnimal(false, field, loc);
 96					newAnimals.add(young);
 97				}
 98			}
 99		}
