143				}
144				sickStep++;
145				FieldEnvironment field = getField();
146				if (field != null) {
147					List<Location> adjacent = field.getAdjacentAnimalLocations(getLocation());
148					Iterator<Location> it = adjacent.iterator();
149					while (it.hasNext()) {
150						Location where = it.next();
151						Animal nearAnimal = field.getAnimalAt(where);
152						if (nearAnimal != null && nearAnimal.getClass().equals(getClass())) {
153							nearAnimal.becomeSick();
154						}
155					}
156					this.notSick();
157				}
158			} else {
159				becomeSick();
160			}
161		}
